import { useEffect, useMemo, useState } from "react";
import { useAuth } from "@/_core/hooks/useAuth";
import { startLogin } from "@/const";
import { Button } from "@/components/ui/button";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { trpc } from "@/lib/trpc";
import { DoctorEditor } from "@/components/DoctorEditor";
import { buildPublicInviteLink } from "@/lib/inviteLink";
import { MapView } from "@/components/Map";
import { WarehouseHeroesWorkspace } from "@/pages/WarehouseHeroesWorkspace";
import SurgeryCalendar from "@/pages/SurgeryCalendar";
import AdminDiagnostics from "@/pages/AdminDiagnostics";
import SurgeryReadiness from "@/pages/SurgeryReadiness";
import { Users, Map, ClipboardList, MessageSquare, BarChart3, Globe2, Activity, AlertTriangle, Plus, LogOut, ShieldCheck, Search, Menu, X, Send, UserPlus, Truck, type LucideIcon } from "lucide-react";

const nav = [
  { id: "dashboard", label: "Dashboard", icon: Activity },
  { id: "delegates", label: "Delegates", icon: Users },
  { id: "warehouse-heroes", label: "Warehouse Heroes", icon: Truck },
  { id: "clients", label: "Clients", icon: Globe2 },
  { id: "tasks", label: "Tasks", icon: ClipboardList },
  { id: "surgeries", label: "Surgeries", icon: Activity },
  { id: "surgery-calendar", label: "Surgery Calendar", icon: Activity },
  { id: "surgery-readiness", label: "Pre-op Readiness", icon: ClipboardList },
  { id: "plans", label: "Visit Plans", icon: ClipboardList },
  { id: "messages", label: "Messages", icon: MessageSquare },
  { id: "reports", label: "Reports", icon: BarChart3 },
  { id: "geography", label: "Geography", icon: Map },
  { id: "admin", label: "Administration", icon: ShieldCheck },
  { id: "diagnostics", label: "Diagnostics", icon: AlertTriangle },
];



const stats: { label: string; value: string; detail: string; icon: LucideIcon; tone: string }[] = [
  { label: "Active Delegates", value: "12", detail: "↑ 8% this month", icon: Users, tone: "blue" },
  { label: "Visits Today", value: "28", detail: "6 in progress", icon: ClipboardList, tone: "teal" },
  { label: "Pending Tasks", value: "07", detail: "Needs attention", icon: Activity, tone: "amber" },
  { label: "Coverage", value: "94%", detail: "Across 6 regions", icon: Globe2, tone: "violet" },
];

function initials(name: string) { return name.split(" ").map((part) => part[0]).join("").slice(0, 2); }

export default function Home() {
  const { user, loading, isAuthenticated, logout } = useAuth();
  const [active, setActive] = useState(() => { const requested = new URLSearchParams(window.location.search).get("workspace"); return nav.some((item) => item.id === requested) ? requested! : "dashboard"; });
  const [mobileOpen, setMobileOpen] = useState(false);
  const [query, setQuery] = useState("");
  const [message, setMessage] = useState("");
  const [messageRecipientId, setMessageRecipientId] = useState("");
  const [clientName, setClientName] = useState("");
  const [clientCity, setClientCity] = useState("");
  const [clientContact, setClientContact] = useState("");
  const [editingClientId, setEditingClientId] = useState<number | null>(null);
  const [doctorName, setDoctorName] = useState("");
  const [doctorClientId, setDoctorClientId] = useState("");
  const [doctorSpecialty, setDoctorSpecialty] = useState("");
  const [editingDoctorId, setEditingDoctorId] = useState<number | null>(null);
  const [doctorRelationship, setDoctorRelationship] = useState<"new" | "warm" | "kol" | "cold">("new");
  const [geoName, setGeoName] = useState("");
  const [geoKind, setGeoKind] = useState<"province" | "city">("province");
  const [geoParentId, setGeoParentId] = useState("");
  const [editingGeographyId, setEditingGeographyId] = useState<number | null>(null);
  const [editingSurgeryId, setEditingSurgeryId] = useState<number | null>(null);
  const [surgeryStatus, setSurgeryStatus] = useState<"pending" | "partial" | "collected">("pending");
  const [surgeryNotes, setSurgeryNotes] = useState("");
  const [surgeryQuotation, setSurgeryQuotation] = useState("");
  const [surgeryInvoice, setSurgeryInvoice] = useState("");
  const [newSurgeryDelegateId, setNewSurgeryDelegateId] = useState("");
  const [newSurgeryClientId, setNewSurgeryClientId] = useState("");
  const [newSurgeryDate, setNewSurgeryDate] = useState("");
  const [newSurgeryProcedure, setNewSurgeryProcedure] = useState("");
  const [newSurgeryHospital, setNewSurgeryHospital] = useState("");
  const [newSurgerySurgeon, setNewSurgerySurgeon] = useState("");
  const [taskClientId, setTaskClientId] = useState("");
  const [taskDelegateId, setTaskDelegateId] = useState("");
  const [taskDate, setTaskDate] = useState("");
  const [workspaceNotice, setWorkspaceNotice] = useState("");
  const [newUserEmail, setNewUserEmail] = useState("");
  const [inviteRole, setInviteRole] = useState<"delegate" | "manager" | "warehouse_hero" | "user">("delegate");
  const [assignmentManagerId, setAssignmentManagerId] = useState("");
  const [assignmentDelegateId, setAssignmentDelegateId] = useState("");
  const [adminNotice, setAdminNotice] = useState("");
  const [inviteUrl, setInviteUrl] = useState("");
  const [copyNotice, setCopyNotice] = useState("");
  const [fromDate, setFromDate] = useState("");
  const [toDate, setToDate] = useState("");
  const [showWelcome, setShowWelcome] = useState(() => localStorage.getItem("ffm-manager-onboarding") !== "1");
  const isAdmin = user?.role === "admin" || user?.email?.toLowerCase() === "dr.seleam@gmail.com";
  const usersQuery = trpc.admin.users.useQuery(undefined, { enabled: isAdmin && active === "admin" });
  const invitationsQuery = trpc.admin.invitations.useQuery(undefined, { enabled: isAdmin && active === "admin" });
  const managersQuery = trpc.admin.managers.useQuery(undefined, { enabled: isAdmin && active === "admin" });
  const adminDelegatesQuery = trpc.admin.delegates.useQuery(undefined, { enabled: isAdmin && active === "admin" });
  const assignmentsQuery = trpc.admin.managerAssignments.useQuery(undefined, { enabled: isAdmin && active === "admin" });
  const clientErrorsQuery = trpc.monitoring.recentClientErrors.useQuery(undefined, { enabled: isAdmin && active === "admin" });
  const monitoringHealthQuery = trpc.monitoring.health.useQuery(undefined, { enabled: isAdmin && active === "admin" });
  const backupReminderQuery = trpc.monitoring.weeklyBackupReminder.useQuery(undefined, { enabled: isAdmin && active === "admin" });
  const addUser = trpc.admin.addUser.useMutation({ onSuccess: () => { setNewUserEmail(""); setAdminNotice("User added to the FFM directory."); usersQuery.refetch(); } });
  const createInvitation = trpc.admin.createInvitation.useMutation({ onSuccess: (result) => { setNewUserEmail(""); setInviteRole("delegate"); setInviteUrl(buildPublicInviteLink(window.location, result.inviteUrl)); invitationsQuery.refetch(); setAdminNotice(`Delegate invitation created for ${result.invitation?.email || "the invited email"}. Share the secure link with the invited user.`); usersQuery.refetch(); } });
  const assignDelegate = trpc.admin.assignDelegate.useMutation({ onSuccess: () => { setAssignmentDelegateId(""); setAdminNotice("Delegate assigned to manager."); assignmentsQuery.refetch(); } });
  const unassignDelegate = trpc.admin.unassignDelegate.useMutation({ onSuccess: () => { setAdminNotice("Delegate unassigned from manager."); assignmentsQuery.refetch(); } });
  const setRole = trpc.admin.setRole.useMutation({ onSuccess: () => { setAdminNotice("User role updated."); usersQuery.refetch(); } });
  const removeUser = trpc.admin.removeUser.useMutation({ onSuccess: () => { setAdminNotice("User removed from the FFM directory."); usersQuery.refetch(); } });
  const adminError = usersQuery.error?.message || addUser.error?.message || createInvitation.error?.message || assignDelegate.error?.message || unassignDelegate.error?.message || setRole.error?.message || removeUser.error?.message;
  const clientsQuery = trpc.operations.clients.useQuery(undefined, { enabled: isAuthenticated });
  const delegatesQuery = trpc.operations.delegates.useQuery(undefined, { enabled: isAuthenticated });
  const doctorsQuery = trpc.operations.doctors.useQuery(undefined, { enabled: isAuthenticated });
  const geographyQuery = trpc.operations.geography.useQuery(undefined, { enabled: isAuthenticated });
  const tasksQuery = trpc.operations.tasks.useQuery(undefined, { enabled: isAuthenticated });
  const surgeriesQuery = trpc.operations.surgeries.useQuery(undefined, { enabled: isAuthenticated && active === "surgeries" });
  const visitPlansQuery = trpc.operations.visitPlans.useQuery(undefined, { enabled: isAuthenticated && active === "plans" });
  const livePositionsQuery = trpc.operations.liveDelegatePositions.useQuery(undefined, { enabled: isAuthenticated && active === "dashboard", refetchInterval: 30000 });
  const livePositionMarkers = (livePositionsQuery.data ?? []).flatMap((position) => { const latitude = Number(position.latitude); const longitude = Number(position.longitude); return Number.isFinite(latitude) && Number.isFinite(longitude) ? [{ id: `delegate-${position.delegateId}`, position: { lat: latitude, lng: longitude }, title: position.delegateName || position.delegateEmail || `Delegate #${position.delegateId}` }] : []; });
  const clientMarkers = (clientsQuery.data ?? []).flatMap((client) => { const latitude = Number(client.latitude); const longitude = Number(client.longitude); return Number.isFinite(latitude) && Number.isFinite(longitude) ? [{ id: client.id, position: { lat: latitude, lng: longitude }, title: client.name }] : []; });
  const selectedSurgeryClient = (clientsQuery.data ?? []).find((client) => String(client.id) === newSurgeryClientId);
  const selectedSurgeryClientDoctors = selectedSurgeryClient ? (doctorsQuery.data ?? []).filter((doctor) => doctor.clientId === selectedSurgeryClient.id) : [];
  useEffect(() => {
    const selectedHospital = selectedSurgeryClient?.name ?? "";
    if (newSurgeryHospital !== selectedHospital) setNewSurgeryHospital(selectedHospital);
    if (!selectedSurgeryClientDoctors.some((doctor) => doctor.name === newSurgerySurgeon)) setNewSurgerySurgeon("");
  }, [selectedSurgeryClient, selectedSurgeryClientDoctors, newSurgeryHospital, newSurgerySurgeon]);
  useEffect(() => {
    if (active !== "surgeries") return;
    const hospitalInput = document.querySelector<HTMLInputElement>('input[aria-label="Surgery hospital"]');
    const surgeonInput = document.querySelector<HTMLInputElement>('input[aria-label="Surgery surgeon"]');
    if (!hospitalInput || !surgeonInput) return;
    hospitalInput.readOnly = true;
    hospitalInput.title = "Hospital is selected automatically from the client.";
    const listId = "surgery-client-doctors";
    let options = document.getElementById(listId) as HTMLDataListElement | null;
    if (!options) { options = document.createElement("datalist"); options.id = listId; document.body.appendChild(options); }
    options.replaceChildren(...selectedSurgeryClientDoctors.map((doctor) => { const option = document.createElement("option"); option.value = doctor.name; option.label = doctor.specialty ? `${doctor.name} — ${doctor.specialty}` : doctor.name; return option; }));
    surgeonInput.setAttribute("list", listId);
    surgeonInput.placeholder = selectedSurgeryClient ? (selectedSurgeryClientDoctors.length ? "Select surgeon from this client" : "No registered doctors for this client") : "Select client first";
    surgeonInput.disabled = !selectedSurgeryClient || !selectedSurgeryClientDoctors.length;
  }, [active, selectedSurgeryClient, selectedSurgeryClientDoctors]);
  const messagesQuery = trpc.operations.messages.useQuery(undefined, { enabled: isAuthenticated });
  const unreadMessageCount = messagesQuery.data?.filter((item) => item.recipientId === user?.id && !item.readAt).length ?? 0;
  const visibleDelegates = useMemo(() => (delegatesQuery.data || []).filter((delegate) => `${delegate.name || ""} ${delegate.email || ""}`.toLowerCase().includes(query.toLowerCase())), [delegatesQuery.data, query]);
  const resetClientForm = () => { setEditingClientId(null); setClientName(""); setClientCity(""); setClientContact(""); };
  const addClient = trpc.operations.addClient.useMutation({ onSuccess: () => { resetClientForm(); setWorkspaceNotice("Client created in the FFM database."); clientsQuery.refetch(); } });
  const updateClient = trpc.operations.updateClient.useMutation({ onSuccess: () => { resetClientForm(); setWorkspaceNotice("Client updated in the FFM database."); clientsQuery.refetch(); } });
  const removeClient = trpc.operations.removeClient.useMutation({ onSuccess: () => { if (editingClientId) resetClientForm(); setWorkspaceNotice("Client removed from the FFM database."); clientsQuery.refetch(); }, onError: (error) => setWorkspaceNotice(error.message) });
  const resetDoctorForm = () => { setEditingDoctorId(null); setDoctorName(""); setDoctorSpecialty(""); setDoctorClientId(""); setDoctorRelationship("new"); };
  const addDoctor = trpc.operations.addDoctor.useMutation({ onSuccess: () => { resetDoctorForm(); setWorkspaceNotice("Doctor created in the FFM database."); doctorsQuery.refetch(); } });
  const updateDoctor = trpc.operations.updateDoctor.useMutation({ onSuccess: () => { resetDoctorForm(); setWorkspaceNotice("Doctor updated in the FFM database."); doctorsQuery.refetch(); } });
  const removeDoctor = trpc.operations.removeDoctor.useMutation({ onSuccess: () => { resetDoctorForm(); setWorkspaceNotice("Doctor removed from the FFM database."); doctorsQuery.refetch(); }, onError: (error) => setWorkspaceNotice(error.message) });
  const resetGeographyForm = () => { setEditingGeographyId(null); setGeoName(""); setGeoKind("province"); setGeoParentId(""); };
  const addGeography = trpc.operations.addGeography.useMutation({ onSuccess: () => { resetGeographyForm(); setWorkspaceNotice("Geography record created in the FFM database."); geographyQuery.refetch(); } });
  const updateGeography = trpc.operations.updateGeography.useMutation({ onSuccess: () => { resetGeographyForm(); setWorkspaceNotice("Geography record updated in the FFM database."); geographyQuery.refetch(); } });
  const removeGeography = trpc.operations.removeGeography.useMutation({ onSuccess: () => { resetGeographyForm(); setWorkspaceNotice("Geography record removed from the FFM database."); geographyQuery.refetch(); }, onError: (error) => setWorkspaceNotice(error.message) });
  const addTask = trpc.operations.addTask.useMutation({ onSuccess: () => { setTaskClientId(""); setTaskDelegateId(""); setTaskDate(""); setWorkspaceNotice("Task created and assigned."); tasksQuery.refetch(); } });
  const updateTaskStatus = trpc.operations.updateTaskStatus.useMutation({ onSuccess: () => { setWorkspaceNotice("Task status updated."); tasksQuery.refetch(); } });
  const reviewVisitPlan = trpc.operations.reviewVisitPlan.useMutation({ onSuccess: () => { setWorkspaceNotice("Visit plan review status updated."); visitPlansQuery.refetch(); }, onError: (error) => setWorkspaceNotice(error.message) });
  const createManagerSurgery = trpc.operations.createManagerSurgery.useMutation({ onSuccess: () => { setNewSurgeryDelegateId(""); setNewSurgeryClientId(""); setNewSurgeryDate(""); setNewSurgeryProcedure(""); setNewSurgeryHospital(""); setNewSurgerySurgeon(""); setWorkspaceNotice("Surgery record created for the assigned Delegate."); surgeriesQuery.refetch(); }, onError: (error) => setWorkspaceNotice(error.message) });
  const updateSurgery = trpc.operations.updateSurgery.useMutation({ onSuccess: () => { setEditingSurgeryId(null); setSurgeryQuotation(""); setSurgeryInvoice(""); setSurgeryNotes(""); setWorkspaceNotice("Surgery details updated."); surgeriesQuery.refetch(); }, onError: (error) => setWorkspaceNotice(error.message) });
  const removeSurgery = trpc.operations.removeSurgery.useMutation({ onSuccess: () => { setEditingSurgeryId(null); setWorkspaceNotice("Surgery and its registered implant and proof metadata were deleted."); surgeriesQuery.refetch(); }, onError: (error) => setWorkspaceNotice(error.message) });
  const sendMessage = trpc.operations.sendMessage.useMutation({ onSuccess: () => { setMessage(""); setMessageRecipientId(""); setWorkspaceNotice("Direct message sent to the assigned Delegate."); messagesQuery.refetch(); } });
  const reportFilters = useMemo(() => ({ from: fromDate || undefined, to: toDate || undefined }), [fromDate, toDate]);
  const summaryQuery = trpc.reports.summary.useQuery(reportFilters, { enabled: isAuthenticated && active === "reports" });
  const exportQuery = trpc.reports.exportCsv.useQuery(reportFilters, { enabled: false });
  const auditQuery = trpc.reports.audit.useQuery({ limit: 20 }, { enabled: isAdmin && active === "admin" });
  const downloadReport = async () => { const result = await exportQuery.refetch(); if (result.data) { const blob = new Blob([result.data], { type: "text/csv" }); const url = URL.createObjectURL(blob); const anchor = document.createElement("a"); anchor.href = url; anchor.download = "ffm-operational-summary.csv"; anchor.click(); URL.revokeObjectURL(url); } };
  const copyInviteLink = async () => { if (!inviteUrl) return; try { if (navigator.clipboard?.writeText) { await navigator.clipboard.writeText(inviteUrl); } else { const field = document.createElement("textarea"); field.value = inviteUrl; field.setAttribute("readonly", ""); field.style.position = "fixed"; field.style.opacity = "0"; document.body.appendChild(field); field.select(); const copied = document.execCommand("copy"); field.remove(); if (!copied) throw new Error("Clipboard permission was denied"); } setCopyNotice("Invite link copied."); } catch { setCopyNotice("Copy was blocked. Select the link and copy it manually."); } };
  const liveStats = stats.map((item) => item.label === "Active Delegates" ? { ...item, value: delegatesQuery.isLoading ? "—" : String(delegatesQuery.data?.length ?? 0), detail: delegatesQuery.isLoading ? "Syncing database" : "Assigned live delegates" } : item.label === "Visits Today" ? { ...item, value: tasksQuery.isLoading ? "—" : String(tasksQuery.data?.length ?? 0), detail: tasksQuery.isLoading ? "Syncing database" : "Live task records" } : item.label === "Pending Tasks" ? { ...item, value: tasksQuery.isLoading ? "—" : String(tasksQuery.data?.filter((task) => task.status === "pending").length ?? 0), detail: tasksQuery.isLoading ? "Syncing database" : "Live pending tasks" } : item.label === "Coverage" ? { ...item, value: clientsQuery.isLoading ? "—" : String(clientsQuery.data?.length ?? 0), detail: clientsQuery.isLoading ? "Syncing database" : "Live client records" } : item);

  if (loading) return <div className="blueprint-page"><div className="blueprint-loader">Loading FFM Manager…</div></div>;
  if (!isAuthenticated) return <div className="blueprint-page login-view"><div className="blueprint-grid" /><Card className="login-card blueprint-card"><div className="logo-mark">FFM</div><p className="eyebrow">FIELD FORCE MANAGEMENT</p><h1>FFM Manager</h1><p className="muted">Secure control panel for delegates, visits, clients, and clinical operations.</p><Button className="w-full mt-6 blueprint-button" onClick={() => startLogin()}>Sign in securely</Button><p className="login-note">Authentication is required for all app access.</p></Card></div>;

  const current = nav.find((item) => item.id === active) ?? nav[0];
  if (active === "warehouse-heroes") return <WarehouseHeroesWorkspace isAdmin={isAdmin} onBack={() => setActive("dashboard")} />;
  if (active === "surgery-calendar") return <SurgeryCalendar />;
  if (active === "surgery-readiness") return <SurgeryReadiness />;
  if (active === "diagnostics") return <AdminDiagnostics />;

  return <div className="manager-shell">
    <aside className={`manager-sidebar ${mobileOpen ? "open" : ""}`}>
      <div className="brand-lockup"><div className="logo-mark small">FFM</div><div><strong>FFM Manager</strong><span>Control Panel</span></div><button className="mobile-close" onClick={() => setMobileOpen(false)}><X size={18}/></button></div>
      <div className="sidebar-rule" />
      <p className="sidebar-kicker">Operations</p>
      <nav>{nav.filter((item) => (item.id !== "admin" && item.id !== "diagnostics") || isAdmin).map((item) => { const Icon = item.icon; return <button key={item.id} className={`sidebar-link ${active === item.id ? "active" : ""}`} onClick={() => { setActive(item.id); setMobileOpen(false); }}><Icon size={17}/><span>{item.label}</span>{item.id === "messages" && messagesQuery.data && unreadMessageCount > 0 ? <b>{unreadMessageCount}</b> : null}</button>; })}</nav>
      <div className="sidebar-user"><div className="avatar">{initials(user?.name || user?.email || "FFM")}</div><div className="user-copy"><strong>{user?.name || "Authenticated user"}</strong><span>{isAdmin ? "Administrator" : user?.email || "Delegate"}</span></div><button className="logout-icon" onClick={() => logout()} title="Sign out"><LogOut size={16}/></button></div>
    </aside>
    {mobileOpen && <button className="sidebar-scrim" onClick={() => setMobileOpen(false)} aria-label="Close navigation"/>}
    <main className="manager-main">
      <header className="manager-topbar"><button className="mobile-menu" onClick={() => setMobileOpen(true)}><Menu size={20}/></button><div><p className="topbar-kicker">FFM / {current.label.toUpperCase()}</p><h2>{current.label}</h2></div><div className="topbar-actions"><div className="live-indicator"><span /> Live system</div><Button variant="outline" size="sm" onClick={() => logout()}><LogOut size={14}/> Sign out</Button></div></header>
      <section className="manager-content">{showWelcome && <div className="welcome-banner"><div><p className="eyebrow">WELCOME TO FFM</p><strong>Start with your operational overview</strong><p className="muted">Use Administration to invite users, Tasks to assign work, and Reports to export filtered summaries.</p></div><Button variant="outline" onClick={() => { localStorage.setItem("ffm-manager-onboarding", "1"); setShowWelcome(false); }}>Got it</Button></div>}
        {active === "dashboard" && <>
          <div className="page-intro"><div><p className="eyebrow">Operational overview</p><h1>Good day, {user?.name?.split(" ")[0] || "Manager"}.</h1><p className="muted">A precise view of today’s field activity across the FFM network.</p></div><Button className="blueprint-button" onClick={() => setActive("tasks")}><Plus size={16}/> Create task</Button></div>
          <div className="stat-grid">{liveStats.map(({ label, value, detail, icon: Icon, tone }) => <Card key={label} className="stat-card"><CardContent><div className={`stat-icon ${tone}`}><Icon size={20}/></div><div className="stat-value">{value}</div><div className="stat-label">{label}</div><div className="stat-detail">{detail}</div></CardContent></Card>)}</div>
          <div className="dashboard-grid"><Card className="blueprint-card map-card"><CardHeader><div><CardTitle>Live delegate positions</CardTitle><p className="muted">Real-time field activity · updated every 30 seconds</p></div><Badge className="status-live"><span/> LIVE</Badge></CardHeader><CardContent><div className="map-placeholder"><div className="map-grid"/>{livePositionsQuery.isLoading ? <div className="admin-feedback">Loading privacy-approved live positions…</div> : livePositionsQuery.error ? <div className="admin-feedback error">{livePositionsQuery.error.message}</div> : livePositionMarkers.length ? <MapView className="manager-live-map" initialCenter={{lat:24.7136,lng:46.6753}} initialZoom={7} markers={livePositionMarkers}/> : <div className="admin-feedback">No recent shared Delegate positions are available. Visit GPS records appear here only when the Delegate has enabled location sharing.</div>}</div></CardContent></Card><Card className="blueprint-card"><CardHeader><div><CardTitle>Today's activity</CardTitle><p className="muted">Latest events from your team</p></div><Button variant="ghost" size="sm" onClick={() => setActive("reports")}>View all</Button></CardHeader><CardContent><div className="activity-list">{tasksQuery.isLoading ? <div className="admin-feedback">Loading live activity…</div> : tasksQuery.data?.length ? tasksQuery.data.slice(0, 5).map((task, i) => <div className="activity-row" key={task.id}><div className={`activity-dot ${i === 0 ? "teal" : i === 1 ? "blue" : "amber"}`} /><div><strong>{task.clientName}</strong><span>Delegate #{task.delegateId} · {new Date(task.scheduledAt).toLocaleString()}</span></div><Badge variant="outline">{task.status.replace("_", " ")}</Badge></div>) : <div className="admin-feedback">No live task activity yet.</div>}</div></CardContent></Card></div>
        </>}
        {active === "delegates" && <section className="blueprint-card section-card"><div className="section-heading"><div><p className="eyebrow">Team directory</p><h1>Delegates</h1><p className="muted">Manage field representative accounts and activity.</p></div><span className="admin-feedback">Delegates are assigned by the Administrator.</span></div><div className="toolbar"><div className="search-field"><Search size={16}/><Input value={query} onChange={(e) => setQuery(e.target.value)} placeholder="Search delegates or cities…"/></div><Badge variant="outline">{visibleDelegates.length} shown</Badge></div>{delegatesQuery.isLoading ? <div className="admin-feedback">Loading live delegates…</div> : delegatesQuery.error ? <div className="admin-feedback error">{delegatesQuery.error.message}</div> : visibleDelegates.length ? <div className="data-table"><div className="table-row table-head"><span>Delegate</span><span>Email</span><span>Role</span><span>Location sharing</span><span>Last sign-in</span><span>Action</span></div>{visibleDelegates.map((delegate) => <div className="table-row" key={delegate.id}><span className="person-cell"><span className="avatar bg-[#1B6FD8]">{initials(delegate.name || delegate.email || "Delegate")}</span><strong>{delegate.name || "Unnamed delegate"}</strong></span><span>{delegate.email || "—"}</span><span><Badge className="badge-success">{delegate.role}</Badge></span><span><Badge variant="outline">{delegate.locationSharing ? "Enabled" : "Off"}</Badge></span><span>{delegate.lastSignedIn ? new Date(delegate.lastSignedIn).toLocaleDateString() : "Not signed in"}</span><Button variant="ghost" size="sm">Open</Button></div>)}</div> : <div className="admin-feedback">No delegates are assigned to this Manager yet.</div>}</section>}
        {active === "tasks" && <section className="blueprint-card section-card"><div className="section-heading"><div><p className="eyebrow">Field execution</p><h1>Tasks</h1><p className="muted">Assign and track field visits across the network.</p></div><div className="inline-form"><select value={taskClientId} onChange={(e) => setTaskClientId(e.target.value)}><option value="">Choose client</option>{(clientsQuery.data || []).map((client) => <option key={client.id} value={client.id}>{client.name}</option>)}</select><select value={taskDelegateId} onChange={(e) => setTaskDelegateId(e.target.value)}><option value="">Choose delegate</option>{(delegatesQuery.data || []).map((delegate) => <option key={delegate.id} value={delegate.id}>{delegate.name || delegate.email || `Delegate #${delegate.id}`}</option>)}</select><Input type="datetime-local" value={taskDate} onChange={(e) => setTaskDate(e.target.value)}/><Button className="blueprint-button" disabled={!taskClientId || !taskDelegateId || !taskDate || addTask.isPending} onClick={() => addTask.mutate({ clientId: Number(taskClientId), delegateId: Number(taskDelegateId), scheduledAt: new Date(taskDate) })}><Plus size={16}/>{addTask.isPending ? "Saving…" : "Create task"}</Button></div></div>{workspaceNotice && <div className="admin-feedback success">{workspaceNotice}</div>}<div className="task-stack">{tasksQuery.isLoading ? <div className="admin-feedback">Loading live tasks…</div> : tasksQuery.data?.length ? tasksQuery.data.map((task) => <div className="task-item" key={task.id}><div className="task-status-bar"/><div className="task-copy"><strong>{task.clientName}</strong><span>Delegate #{task.delegateId} · {new Date(task.scheduledAt).toLocaleString()}</span></div><Badge className={task.status === "completed" ? "badge-success" : "badge-warning"}>{task.status.replace("_", " ")}</Badge><Button variant="ghost" size="sm" disabled={updateTaskStatus.isPending} onClick={() => updateTaskStatus.mutate({ id: task.id, status: task.status === "completed" ? "pending" : "completed" })}>{task.status === "completed" ? "Reopen" : "Complete"}</Button></div>) : <div className="admin-feedback">No live tasks yet.</div>}</div></section>}
        {active === "surgeries" && <section className="blueprint-card section-card"><div className="section-heading"><div><p className="eyebrow">Clinical execution</p><h1>Surgeries</h1><p className="muted">Create and maintain surgery records for Delegates assigned to this Manager.</p></div></div><div className="inline-form"><select aria-label="Surgery Delegate" value={newSurgeryDelegateId} onChange={(e) => setNewSurgeryDelegateId(e.target.value)}><option value="">Choose assigned Delegate</option>{(delegatesQuery.data || []).map((delegate) => <option key={delegate.id} value={delegate.id}>{delegate.name || delegate.email || `Delegate #${delegate.id}`}</option>)}</select><select aria-label="Surgery client" value={newSurgeryClientId} onChange={(e) => setNewSurgeryClientId(e.target.value)}><option value="">Choose client</option>{(clientsQuery.data || []).map((client) => <option key={client.id} value={client.id}>{client.name}</option>)}</select><Input aria-label="Surgery procedure" value={newSurgeryProcedure} onChange={(e) => setNewSurgeryProcedure(e.target.value)} placeholder="Procedure name"/><Input aria-label="Surgery date" type="date" value={newSurgeryDate} onChange={(e) => setNewSurgeryDate(e.target.value)}/><Input aria-label="Surgery hospital" value={newSurgeryHospital} onChange={(e) => setNewSurgeryHospital(e.target.value)} placeholder="Hospital (optional)"/><Input aria-label="Surgery surgeon" value={newSurgerySurgeon} onChange={(e) => setNewSurgerySurgeon(e.target.value)} placeholder="Surgeon (optional)"/><Button className="blueprint-button" disabled={!newSurgeryDelegateId || !newSurgeryClientId || !newSurgeryDate || !newSurgeryProcedure.trim() || createManagerSurgery.isPending} onClick={() => createManagerSurgery.mutate({ delegateId: Number(newSurgeryDelegateId), clientId: Number(newSurgeryClientId), surgeryDate: new Date(newSurgeryDate), procedureName: newSurgeryProcedure.trim(), hospital: newSurgeryHospital.trim() || undefined, surgeon: newSurgerySurgeon.trim() || undefined })}>{createManagerSurgery.isPending ? "Creating…" : "Create surgery"}</Button></div>{workspaceNotice && <div className={createManagerSurgery.error ? "admin-feedback error" : "admin-feedback success"}>{workspaceNotice}</div>}{surgeriesQuery.isLoading ? <div className="admin-feedback">Loading live surgeries…</div> : surgeriesQuery.error ? <div className="admin-feedback error">Unable to load surgeries: {surgeriesQuery.error.message}</div> : surgeriesQuery.data?.length ? <div className="data-table"><div className="table-row table-head"><span>Date</span><span>Client</span><span>Delegate</span><span>Procedure</span><span>Status</span><span>Notes</span><span>Action</span></div>{surgeriesQuery.data.map((surgery) => <div className="table-row" key={surgery.id}><span>{new Date(surgery.surgeryDate).toLocaleDateString()}</span><span>{clientsQuery.data?.find((client) => client.id === surgery.clientId)?.name || `Client #${surgery.clientId}`}</span><span>Delegate #{surgery.delegateId}</span><span>{surgery.procedureName}</span><span>{editingSurgeryId === surgery.id ? <select className="blueprint-input" value={surgeryStatus} onChange={(e) => setSurgeryStatus(e.target.value as "pending" | "partial" | "collected")}><option value="pending">Pending</option><option value="partial">Partial</option><option value="collected">Collected</option></select> : <Badge variant="outline">{surgery.status}</Badge>}</span><span>{editingSurgeryId === surgery.id ? <div className="inline-form"><Input value={surgeryQuotation} onChange={(e) => setSurgeryQuotation(e.target.value)} placeholder="Quotation"/><Input value={surgeryInvoice} onChange={(e) => setSurgeryInvoice(e.target.value)} placeholder="Invoice"/><Input value={surgeryNotes} onChange={(e) => setSurgeryNotes(e.target.value)} placeholder="Notes"/></div> : <>{surgery.notes || "—"}{(surgery.quotation || surgery.invoice) && <small className="block muted">{surgery.quotation ? `Quotation: ${surgery.quotation}` : ""}{surgery.invoice ? ` · Invoice: ${surgery.invoice}` : ""}</small>}</>}</span><span className="admin-actions">{editingSurgeryId === surgery.id ? <><Button variant="ghost" size="sm" disabled={updateSurgery.isPending} onClick={() => updateSurgery.mutate({ id: surgery.id, status: surgeryStatus, notes: surgeryNotes || undefined, quotation: surgeryQuotation || undefined, invoice: surgeryInvoice || undefined })}>{updateSurgery.isPending ? "Saving…" : "Save"}</Button><Button variant="ghost" size="sm" onClick={() => setEditingSurgeryId(null)}>Cancel</Button></> : <><Button variant="ghost" size="sm" onClick={() => { setEditingSurgeryId(surgery.id); setSurgeryStatus(surgery.status); setSurgeryNotes(surgery.notes || ""); setSurgeryQuotation(surgery.quotation || ""); setSurgeryInvoice(surgery.invoice || ""); setWorkspaceNotice(""); }}>Edit</Button>{isAdmin && <Button variant="destructive" size="sm" disabled={removeSurgery.isPending} onClick={() => { if (window.confirm(`Delete ${surgery.procedureName || "this surgery"}? Registered implant and delivery-proof metadata will also be deleted.`)) removeSurgery.mutate({ id: surgery.id }); }}>{removeSurgery.isPending ? "Deleting…" : "Delete"}</Button>}</>}</span></div>)}</div> : <div className="admin-feedback">No live surgery records are available for assigned delegates.</div>}</section>}
        {active === "plans" && <section className="blueprint-card section-card"><div className="section-heading"><div><p className="eyebrow">Route governance</p><h1>Visit Plans</h1><p className="muted">Review proposed visits from delegates assigned to this Manager.</p></div></div>{workspaceNotice && <div className="admin-feedback success">{workspaceNotice}</div>}{visitPlansQuery.isLoading ? <div className="admin-feedback">Loading live visit plans…</div> : visitPlansQuery.error ? <div className="admin-feedback error">Unable to load visit plans: {visitPlansQuery.error.message}</div> : visitPlansQuery.data?.length ? <div className="data-table"><div className="table-row table-head"><span>Proposed</span><span>Client</span><span>Delegate</span><span>Status</span><span>Action</span></div>{visitPlansQuery.data.map((plan) => <div className="table-row" key={plan.id}><span>{new Date(plan.proposedAt).toLocaleString()}</span><span>{clientsQuery.data?.find((client) => client.id === plan.clientId)?.name || `Client #${plan.clientId}`}</span><span>Delegate #{plan.delegateId}</span><span><Badge variant="outline">{plan.status}</Badge></span><span className="admin-actions"><Button variant="ghost" size="sm" disabled={reviewVisitPlan.isPending} onClick={() => reviewVisitPlan.mutate({ id: plan.id, status: plan.status === "approved" ? "rejected" : "approved" })}>{plan.status === "approved" ? "Reject" : "Approve"}</Button></span></div>)}</div> : <div className="admin-feedback">No proposed visit plans are waiting for review.</div>}</section>}
        {active === "messages" && <section className="blueprint-card section-card"><div className="section-heading"><div><p className="eyebrow">Team communication</p><h1>Messages</h1><p className="muted">Send a direct operational message to one of your assigned Delegates.</p></div></div><div className="message-composer"><Label htmlFor="message-recipient">Recipient</Label><select id="message-recipient" className="blueprint-input" value={messageRecipientId} onChange={(e) => setMessageRecipientId(e.target.value)} disabled={delegatesQuery.isLoading || sendMessage.isPending}><option value="">Choose an assigned Delegate</option>{(delegatesQuery.data || []).map((delegate) => <option key={delegate.id} value={delegate.id}>{delegate.name || delegate.email || `Delegate #${delegate.id}`}</option>)}</select>{delegatesQuery.error ? <div className="admin-feedback error">Unable to load assigned Delegates: {delegatesQuery.error.message}</div> : !delegatesQuery.isLoading && !(delegatesQuery.data || []).length ? <div className="admin-feedback">No Delegates are currently assigned to you. Ask the Administrator to make an assignment before sending a direct message.</div> : null}<Label htmlFor="direct-message-body">Message</Label><Input id="direct-message-body" value={message} onChange={(e) => setMessage(e.target.value)} placeholder="Write an operational update…"/><div className="composer-footer"><span className="muted">Recipient eligibility is checked again by the server using Administrator-controlled assignments.</span><Button className="blueprint-button" disabled={!message.trim() || !messageRecipientId || sendMessage.isPending} onClick={() => sendMessage.mutate({ recipientId: Number(messageRecipientId), body: message })}><Send size={15}/>{sendMessage.isPending ? "Sending…" : "Send direct message"}</Button></div>{sendMessage.error && <div className="admin-feedback error">{sendMessage.error.message}</div>}</div>{workspaceNotice && <div className="admin-feedback success">{workspaceNotice}</div>}<div className="message-history">{messagesQuery.isLoading ? <div className="admin-feedback">Loading messages…</div> : messagesQuery.data?.length ? messagesQuery.data.slice().reverse().map((item) => <div className="message-history-row" key={item.id}><strong>{item.senderId === user?.id ? "You" : `User #${item.senderId}`}</strong><span>{item.body}</span><time>{new Date(item.createdAt).toLocaleString()}</time></div>) : <div className="admin-feedback">No messages yet.</div>}</div></section>}
        {active === "admin" && isAdmin && <section className="blueprint-card section-card"><div className="section-heading"><div><p className="eyebrow">Access control</p><h1>Administration</h1><p className="muted">Manage FFM users, roles, and access to both apps.</p></div></div><div className="admin-callout"><ShieldCheck size={18}/><div><strong>Administrator account verified</strong><p>{user?.email || "dr.seleam@gmail.com"} is assigned the admin role automatically on first login.</p></div></div><div className="admin-callout"><AlertTriangle size={18}/><div><strong>Weekly backup reminder</strong><p>{backupReminderQuery.isLoading ? "Checking reminder status…" : backupReminderQuery.data?.lastTriggeredAt ? `A fresh backup reminder was last issued ${new Date(backupReminderQuery.data.lastTriggeredAt).toLocaleString()}. It repeats every Thursday at 11:00 a.m. GMT+3.` : backupReminderQuery.data ? "The weekly backup schedule is active. Download a fresh backup copy every Thursday at 11:00 a.m. GMT+3." : "The weekly backup reminder has not been configured yet."}</p></div></div><div className="audit-strip"><ShieldCheck size={16}/><span>{auditQuery.isLoading ? "Loading audit history…" : `${auditQuery.data?.length ?? 0} recent audit events available`}</span></div>{auditQuery.error ? <div className="admin-feedback error">Unable to load activity history: {auditQuery.error.message}</div> : auditQuery.data?.length ? <div className="activity-list admin-activity-list">{auditQuery.data.slice(0, 8).map((event) => <div className="activity-row" key={event.id}><div className="activity-dot blue"/><div><strong>{event.action}</strong><span>{event.entityType}{event.entityId ? ` #${event.entityId}` : ""} · {new Date(event.createdAt).toLocaleString()}</span></div></div>)}</div> : <div className="admin-feedback">No administrator activity has been recorded yet.</div>}<div className="admin-error-health"><div className="audit-strip"><Activity size={16}/><span>{monitoringHealthQuery.isLoading ? "Checking system health…" : monitoringHealthQuery.error ? "System health unavailable" : `Database ${monitoringHealthQuery.data?.database ?? "unknown"} · ${monitoringHealthQuery.data?.auditEvents ?? 0} audit events · ${monitoringHealthQuery.data?.clientErrors ?? 0} captured errors`}</span></div><div className="audit-strip"><AlertTriangle size={16}/><span>{clientErrorsQuery.isLoading ? "Checking client diagnostics…" : `${clientErrorsQuery.data?.length ?? 0} recent client errors captured`}</span></div>{clientErrorsQuery.error ? <div className="admin-feedback error">Unable to load client diagnostics: {clientErrorsQuery.error.message}</div> : clientErrorsQuery.data?.length ? <div className="activity-list admin-activity-list">{clientErrorsQuery.data.slice(0, 5).map((error) => <div className="activity-row" key={error.id}><div className="activity-dot amber"/><div><strong>{error.message}</strong><span>{error.route || "Unknown route"} · {new Date(error.createdAt).toLocaleString()}</span></div></div>)}</div> : <div className="admin-feedback success">No client errors have been captured.</div>}</div><div className="admin-add-row"><Input value={newUserEmail} onChange={(e) => setNewUserEmail(e.target.value)} placeholder="new.user@example.com" type="email"/><select className="admin-role-select" value={inviteRole} onChange={(e) => setInviteRole(e.target.value as "delegate" | "manager" | "user")}><option value="delegate">Delegate</option><option value="manager">Manager</option><option value="user">User</option></select><Button className="blueprint-button" disabled={!newUserEmail || createInvitation.isPending} onClick={() => createInvitation.mutate({ email: newUserEmail, role: inviteRole })}><UserPlus size={15}/> {createInvitation.isPending ? "Creating…" : "Create invitation"}</Button></div>{adminError && <div className="admin-feedback error">{adminError}</div>}{adminNotice && <div className="admin-feedback success">{adminNotice}</div>}{inviteUrl && <div className="invite-link-row"><Input value={inviteUrl} readOnly/><Button variant="outline" onClick={copyInviteLink}>Copy link</Button>{copyNotice && <span className={copyNotice.startsWith("Invite") ? "copy-notice success" : "copy-notice error"}>{copyNotice}</span>}</div>}<div className="invite-summary"><strong>Invitation history</strong>{invitationsQuery.isLoading ? <span>Loading invitations…</span> : invitationsQuery.data?.length ? invitationsQuery.data.slice(-5).reverse().map((invite) => <span key={invite.id}>{invite.email} · {invite.role} · {invite.acceptedAt ? "Accepted" : "Pending"}</span>) : <span>No invitations created yet.</span>}</div>{addUser.isPending || setRole.isPending || removeUser.isPending ? <div className="admin-feedback">Saving administrator changes…</div> : null}{usersQuery.isLoading ? <div className="admin-feedback">Loading users…</div> : usersQuery.data?.length === 0 ? <div className="admin-feedback">No users have been added yet.</div> : null}<div className="data-table"><div className="table-row table-head"><span>User</span><span>Role</span><span>Last sign-in</span><span>Status</span><span>Action</span></div>{(usersQuery.data || []).map((managedUser) => { const protectedUser = managedUser.email?.toLowerCase() === "dr.seleam@gmail.com" || managedUser.openId === user?.openId; return <div className="table-row" key={managedUser.id}><span className="person-cell"><span className="avatar">{initials(managedUser.name || managedUser.email || "U")}</span><strong>{managedUser.email || managedUser.name || "Pending user"}</strong></span><span><select className="admin-role-select compact" value={managedUser.role} disabled={protectedUser || setRole.isPending} onChange={(e) => { if (window.confirm(`Change ${managedUser.email || "this user"}'s role?`)) setRole.mutate({ id: managedUser.id, role: e.target.value as "user" | "manager" | "delegate" | "admin" }); }}><option value="admin">Administrator</option><option value="manager">Manager</option><option value="delegate">Delegate</option><option value="user">User</option></select></span><span>{managedUser.lastSignedIn ? new Date(managedUser.lastSignedIn).toLocaleDateString() : "Not signed in"}</span><span><Badge className="badge-success">Active</Badge></span><span className="admin-actions"><Button variant="ghost" size="sm" disabled={protectedUser || removeUser.isPending} onClick={() => { if (window.confirm(`Remove ${managedUser.email || "this user"} from FFM?`)) removeUser.mutate({ id: managedUser.id }); }}>{removeUser.isPending ? "Removing…" : "Remove"}</Button></span></div>; })}</div></section>}
        {active === "admin" && isAdmin && <section className="blueprint-card section-card mt-4"><div className="section-heading"><div><p className="eyebrow">Team ownership</p><h2>Manager–Delegate assignments</h2><p className="muted">Only the administrator can define which delegates each manager is allowed to manage.</p></div><div className="inline-form"><select className="admin-role-select" value={assignmentManagerId} onChange={(e) => setAssignmentManagerId(e.target.value)}><option value="">Choose manager</option>{managersQuery.data?.map((manager) => <option key={manager.id} value={manager.id}>{manager.name || manager.email || `Manager #${manager.id}`}</option>)}</select><select className="admin-role-select" value={assignmentDelegateId} onChange={(e) => setAssignmentDelegateId(e.target.value)}><option value="">Choose delegate</option>{adminDelegatesQuery.data?.map((delegate) => <option key={delegate.id} value={delegate.id}>{delegate.name || delegate.email || `Delegate #${delegate.id}`}</option>)}</select><Button className="blueprint-button" disabled={!assignmentManagerId || !assignmentDelegateId || assignDelegate.isPending} onClick={() => assignDelegate.mutate({ managerId: Number(assignmentManagerId), delegateId: Number(assignmentDelegateId) })}>{assignDelegate.isPending ? "Assigning…" : "Assign delegate"}</Button></div></div>{assignmentsQuery.isLoading ? <div className="admin-feedback">Loading manager assignments…</div> : assignmentsQuery.error ? <div className="admin-feedback error">{assignmentsQuery.error.message}</div> : assignmentsQuery.data?.length ? <div className="data-table"><div className="table-row table-head"><span>Manager</span><span>Delegate</span><span>Assigned</span><span>Action</span></div>{assignmentsQuery.data.map((assignment) => <div className="table-row" key={assignment.id}><span><strong>{assignment.managerName}</strong></span><span>{assignment.delegateName}</span><span>{new Date(assignment.createdAt).toLocaleDateString()}</span><span><Button variant="ghost" size="sm" disabled={unassignDelegate.isPending} onClick={() => { if (window.confirm(`Unassign ${assignment.delegateName} from ${assignment.managerName}?`)) unassignDelegate.mutate({ id: assignment.id }); }}>{unassignDelegate.isPending ? "Removing…" : "Unassign"}</Button></span></div>)}</div> : <div className="admin-feedback">No manager–delegate assignments exist yet.</div>}</section>}
        {active === "clients" && <section className="blueprint-card section-card"><div className="section-heading"><div><p className="eyebrow">Clinical network</p><h1>Clients</h1><p className="muted">Live hospitals and clinical accounts from the FFM database.</p></div><div className="inline-form"><Input value={clientName} onChange={(e) => setClientName(e.target.value)} placeholder="Hospital or clinical account"/><Input value={clientCity} onChange={(e) => setClientCity(e.target.value)} placeholder="City"/><Input value={clientContact} onChange={(e) => setClientContact(e.target.value)} placeholder="Contact person"/><Button className="blueprint-button" disabled={!clientName.trim() || addClient.isPending || updateClient.isPending} onClick={() => editingClientId ? updateClient.mutate({ id: editingClientId, name: clientName.trim(), city: clientCity || undefined, contactPerson: clientContact || undefined }) : addClient.mutate({ name: clientName.trim(), city: clientCity || undefined, contactPerson: clientContact || undefined })}><Plus size={16}/>{addClient.isPending || updateClient.isPending ? "Saving…" : editingClientId ? "Update client" : "Add client"}</Button>{editingClientId && <Button variant="outline" onClick={resetClientForm}>Cancel</Button>}</div></div>{workspaceNotice && <div className="admin-feedback success">{workspaceNotice}</div>}{clientsQuery.isLoading ? <div className="admin-feedback">Loading live clients…</div> : clientsQuery.error ? <div className="admin-feedback error">{clientsQuery.error.message}</div> : clientsQuery.data?.length ? <div className="data-table"><div className="table-row table-head"><span>Client</span><span>Location</span><span>Contact</span><span>Status</span></div>{clientsQuery.data.map((client) => <div className="table-row" key={client.id}><span><strong>{client.name}</strong></span><span>{client.city || "—"}</span><span>{client.contactPerson || "—"}</span><span><Badge className="badge-success">Active</Badge></span><span className="admin-actions"><Button variant="ghost" size="sm" onClick={() => { setEditingClientId(client.id); setClientName(client.name); setClientCity(client.city || ""); setClientContact(client.contactPerson || ""); setWorkspaceNotice(""); }}>Edit</Button>{isAdmin && <Button variant="destructive" size="sm" disabled={removeClient.isPending} onClick={() => { if (window.confirm(`Delete ${client.name}? Linked doctors, tasks, surgery records, and visit plans must be removed first.`)) removeClient.mutate({ id: client.id }); }}>{removeClient.isPending ? "Deleting…" : "Delete"}</Button>}</span></div>)}</div> : <div className="admin-feedback">No client records yet. Add the first hospital or clinical account.</div>}</section>}
        {active === "clients" && <section className="blueprint-card section-card mt-4"><div className="section-heading"><div><p className="eyebrow">Clinical contacts</p><h2>Doctors</h2><p className="muted">Create and review doctor records linked to live clients.</p></div><DoctorEditor doctor={editingDoctorId ? doctorsQuery.data?.find((doctor) => doctor.id === editingDoctorId) : undefined} clients={clientsQuery.data || []} saving={addDoctor.isPending || updateDoctor.isPending} onCancel={resetDoctorForm} onSave={(draft) => draft.id ? updateDoctor.mutate({ id: draft.id, clientId: draft.clientId, name: draft.name, specialty: draft.specialty, relationship: draft.relationship }) : addDoctor.mutate({ clientId: draft.clientId, name: draft.name, specialty: draft.specialty, relationship: draft.relationship })}/></div>{doctorsQuery.isLoading ? <div className="admin-feedback">Loading doctors…</div> : doctorsQuery.error ? <div className="admin-feedback error">{doctorsQuery.error.message}</div> : <div className="data-table"><div className="table-row table-head"><span>Doctor</span><span>Specialty</span><span>Client</span><span>Relationship</span></div>{doctorsQuery.data?.map((doctor) => <div className="table-row" key={doctor.id}><span><strong>{doctor.name}</strong></span><span>{doctor.specialty || "—"}</span><span>{clientsQuery.data?.find((client) => client.id === doctor.clientId)?.name || "—"}</span><span>{doctor.relationship}</span><span className="admin-actions"><Button variant="ghost" size="sm" onClick={() => { setEditingDoctorId(doctor.id); setWorkspaceNotice(""); }}>Edit</Button>{isAdmin && <Button variant="destructive" size="sm" disabled={removeDoctor.isPending} onClick={() => { if (window.confirm(`Delete ${doctor.name}? Any linked surgery must be deleted first.`)) removeDoctor.mutate({ id: doctor.id }); }}>{removeDoctor.isPending ? "Deleting…" : "Delete"}</Button>}</span></div>)}</div>}</section>}
        {active === "geography" && <section className="blueprint-card section-card"><div className="section-heading"><div><p className="eyebrow">Coverage planning</p><h1>Geography</h1><p className="muted">Create regional coverage records and review them on the live map.</p></div><div className="inline-form"><select className="blueprint-input" value={geoKind} onChange={(e) => { const next = e.target.value as "province" | "city"; setGeoKind(next); if (next === "province") setGeoParentId(""); }}><option value="province">Province</option><option value="city">City</option></select>{geoKind === "city" && <select className="blueprint-input" value={geoParentId} onChange={(e) => setGeoParentId(e.target.value)}><option value="">Parent province</option>{(geographyQuery.data || []).filter((region) => region.kind === "province").map((region) => <option key={region.id} value={region.id}>{region.name}</option>)}</select>}<Input value={geoName} onChange={(e) => setGeoName(e.target.value)} placeholder="Region name"/><Button className="blueprint-button" disabled={!geoName.trim() || addGeography.isPending || updateGeography.isPending} onClick={() => editingGeographyId ? updateGeography.mutate({ id: editingGeographyId, kind: geoKind, name: geoName.trim(), parentId: geoParentId ? Number(geoParentId) : null }) : addGeography.mutate({ kind: geoKind, name: geoName.trim(), parentId: geoParentId ? Number(geoParentId) : null })}>{addGeography.isPending || updateGeography.isPending ? "Saving…" : editingGeographyId ? "Update region" : "Add region"}</Button>{editingGeographyId && <Button variant="outline" onClick={resetGeographyForm}>Cancel</Button>}</div></div>{geographyQuery.isLoading ? <div className="admin-feedback">Loading geography…</div> : geographyQuery.error ? <div className="admin-feedback error">{geographyQuery.error.message}</div> : <div className="data-table mb-4"><div className="table-row table-head"><span>Type</span><span>Name</span><span>Parent</span></div>{geographyQuery.data?.map((region) => <div className="table-row" key={region.id}><span>{region.kind}</span><span><strong>{region.name}</strong></span><span>{region.parentId || "—"}</span><span className="admin-actions"><Button variant="ghost" size="sm" onClick={() => { setEditingGeographyId(region.id); setGeoKind(region.kind); setGeoName(region.name); setGeoParentId(region.parentId ? String(region.parentId) : ""); setWorkspaceNotice(""); }}>Edit</Button><Button variant="ghost" size="sm" disabled={removeGeography.isPending} onClick={() => { if (window.confirm(`Remove ${region.name} from FFM?`)) removeGeography.mutate({ id: region.id }); }}>{removeGeography.isPending ? "Removing…" : "Remove"}</Button></span></div>)}</div>}<MapView className="manager-live-map" initialCenter={{lat:24.7136,lng:46.6753}} initialZoom={7} markers={clientMarkers} route={clientMarkers.length > 1 ? { origin: clientMarkers[0].position, destination: clientMarkers[clientMarkers.length - 1].position, waypoints: clientMarkers.slice(1, -1).map((marker) => ({ location: marker.position, stopover: true })) } : undefined}/></section>}
        {active === "reports" && <section className="blueprint-card section-card"><div className="section-heading"><div><p className="eyebrow">Operational intelligence</p><h1>Reports</h1><p className="muted">Live counts from the FFM operational database.</p></div><div className="report-filters"><Input type="date" value={fromDate} onChange={(e) => setFromDate(e.target.value)} aria-label="Report start date"/><Input type="date" value={toDate} onChange={(e) => setToDate(e.target.value)} aria-label="Report end date"/></div><Button variant="outline" disabled={exportQuery.isFetching} onClick={downloadReport}>{exportQuery.isFetching ? "Preparing…" : "Export report"}</Button></div>{summaryQuery.isLoading ? <div className="admin-feedback">Loading live report data…</div> : summaryQuery.error ? <div className="admin-feedback error">{summaryQuery.error.message}</div> : <div className="report-grid">{[{label:"Clients",value:String(summaryQuery.data?.clients ?? 0),detail:"Database records"},{label:"Total tasks",value:String(summaryQuery.data?.tasks ?? 0),detail:"Assigned work"},{label:"Completed tasks",value:String(summaryQuery.data?.completedTasks ?? 0),detail:"Completed visits"},{label:"Pending tasks",value:String(summaryQuery.data?.pendingTasks ?? 0),detail:"Needs attention"}].map((report) => <Card className="report-card" key={report.label}><CardContent><p className="eyebrow">{report.label}</p><strong>{report.value}</strong><span>{report.detail}</span></CardContent></Card>)}</div>}</section>}
        {!['dashboard', 'delegates', 'tasks', 'surgeries', 'plans', 'messages', 'admin', 'clients', 'reports', 'geography'].includes(active) && <section className="blueprint-card section-card empty-section"><div className="empty-illustration"><Map size={34}/></div><p className="eyebrow">FFM / {current.label.toUpperCase()}</p><h1>{current.label}</h1><p className="muted">This workspace is ready for your live data and operational records.</p><Button className="blueprint-button" onClick={() => setActive("dashboard")}>Return to dashboard</Button></section>}
      </section>
    </main>
  </div>;
}
